select coalesce(m.hissab_week::text,'')||'~'||coalesce(m.partner_etm::text,'')||'~'||coalesce(m.lead_id::text,'')||'~'||coalesce(m.city::text,'')||'~'||coalesce(m.location::text,'')||'~'||coalesce(m.product_type::text,'')||'~'||coalesce(m.revenue_type::text,'')||'~'||coalesce(m.fuel_type::text,'')||'~'||coalesce(m.eip_tag::text,'')||'~'||coalesce(m.active_inactive_flag::text,'')||'~'||coalesce(m.in_car_recovery_hissab_week::text,'')||'~'||coalesce(m.total_os::text,'')||'~'||coalesce(m.weekly_os::text,'')||'~'||coalesce(m.prev_carryforward_os::text,'')||'~'||coalesce(m.total_collected_amount_in_week::text,'')||'~'||coalesce(m.total_collected_100_pct::text,'')||'~'||coalesce(m.collection_till_wed::text,'')||'~'||coalesce(m.os_to_deposit::text,'')||'~'||coalesce(m.partners_not_paid_2_weeks::text,'')||'~'||coalesce(m.last_week_payment_habit::text,'')||'~'||coalesce(m.total_allocated_days::text,'')||'~'||coalesce(m.last_payment_date_till_hissab_week::text,'')||'~'||coalesce(m.last_jama_date::text,'')||'~'||coalesce(m.tenure_days::text,'')||'~'||coalesce(m.week_start_deposit::text,'')||'~'||coalesce(m.week_end_deposit::text,'')||'~'||coalesce(m.bad_debt_amount::text,'')||'~'||coalesce(m.bad_debt_collected::text,'')||'~'||coalesce(m.cars_under_recovery_hissab_week::text,'')||'~'||coalesce(m.recovery_tat::text,'')||'~'||coalesce(m.last_updated::text,'')||'~'||coalesce(m.current_week_nd_count::text,'')||'~'||coalesce(np.n::text,'0')||'~'||coalesce(bd.fb::text,'') r
from analytics.collections_bad_debt_mv m
left join (select partner_etm, count(*) filter (where coalesce(total_collected_amount_in_week,0)=0) n from analytics.collections_bad_debt_mv where for_collections=1 and hissab_week in (date '{W}'-7, date '{W}'-14) group by 1) np on np.partner_etm=m.partner_etm
left join (select partner_etm, min(hissab_week) fb from analytics.collections_bad_debt_mv where bad_debt_amount<0 and hissab_week<=date '{W}' group by 1) bd on bd.partner_etm=m.partner_etm
where m.for_collections=1 and m.hissab_week=date '{W}'